<?php
declare(strict_types=1);
$root=dirname(__DIR__);
$read=static fn(string $path):string=>(string)file_get_contents($root.'/'.$path);
$ok=static function(bool $condition,string $message):void{if(!$condition)throw new RuntimeException($message);};
$migration=$read('database/migrations-local/142_create_waste_trip_completion.sql');
$extensionMigration=$read('database/migrations-local/143_extend_waste_trip_completion_provenance.sql');
$statusMigration=$read('database/migrations-local/144_trip_completion_explicit_statuses.sql');
$service=$read('app/Service/TripCompletionService.php');
$controller=$read('app/Http/Controllers/Company/TripCompletionController.php');
$routes=$read('app/Http/Routes/company_trip_completion.php');
$view=$read('app/View/pages/company_logistics_assistant.php');
$javascript=$read('public/assets/js/trip-completion.js');
$styles=$read('public/assets/css/trip-completion.css');
$registry=$read('app/Security/PageRegistry.php');
foreach(['waste_trip_completion_items','waste_trip_completion_documents','arrived_at','departed_at','driver_signature_present','sender_signature_present','deleted_at']as$token)$ok(str_contains($migration,$token),'Migration missing '.$token);
foreach(['tn_datetime_missing','data_from_tracker','data_from_driver','data_invented']as$token)$ok(str_contains($extensionMigration,$token),'Migration 143 missing '.$token);
foreach(['sender_signature_status','driver_signature_status','tn_datetime_status','recovery_source']as$token)$ok(str_contains($statusMigration,$token),'Migration 144 missing '.$token);
foreach(['/company/logistics-assistant','/report','/package','/documents/{documentId}']as$token)$ok(str_contains($routes,$token),'Route missing '.$token);
$ok(substr_count($routes,'$tripCompletionPage')===11&&str_contains($routes,'/package-stage'),
    'Every registrar endpoint, including chunked package upload, must use the collection permission');
$ok(str_contains($registry,"'company.documents.collection', 'Регистрация времени загрузки', 'Операции', '', 42")
    &&str_contains($registry,"badgeProvider: 'trip_completion_problem'")
    &&str_contains($registry,"badgeProvider: 'tn_review_pending'"),'Registrar and reviewer navigation counters missing');
$ok(str_contains($view,'Регистрация прибытия и убытия у отходообразователя')&&str_contains($view,'Дата и время загрузки по рейсам в процессе вывоза и сданным рейсам.'),'Compact page title missing');
$ok(str_contains($view,'lab-trip-status')&&str_contains($view,'lab-trip-manager')&&str_contains($view,'lab-pickup-address')&&!str_contains($view,'class="lab-trip-label">Перевозчик'),'Trip status, manager, and pickup address missing');
foreach(['Показать все рейсы','Показать все','В работе','На проверке','Архив','Проверено / архив','Передать на проверку','Вернуть на доработку','Переместить в архив','Вернуть из архива','Дата и время прибытия/убытия','ДД.ММ.ГГ ЧЧ:ММ - ЧЧ:ММ','Подпись ОО','Подпись водителя','Дата и время указаны','Данные восстановлены','Со слов вод./мен','+ Добавить скан','Просмотр','Скачать полный комплекс']as$label)$ok(str_contains($view,$label),'UI missing '.$label);
$ok(str_contains($view,'data-review-filters')&&str_contains($view,'registry-ui-tabs')&&str_contains($view,'data-review-tab="all"')&&str_contains($view,'registry-ui-search')&&!str_contains($view,'Показать архив'),'Reviewer filters use the approved tabs and search toolbar');
$ok(!str_contains($view,'lab-review-status'),'Repeated review badges must not appear in trip rows');
$ok(str_contains($routes,"'company.documents.tn_review'")&&str_contains($registry,"'company.documents.tn_review', 'Проверка ТН'")&&substr_count($routes,'$tnReviewPage')===10,'Separate reviewer route and role permission missing');
$ok(!str_contains($view,'Вернуть в работу')&&str_contains($controller,"$".'this->reviewerMode'), 'Registrar and reviewer actions must be separated');
$ok(!str_contains($view,'Подпись Отходообразователя')&&!str_contains($view,'Придуманы')&&!str_contains($view,'lab-trip-email'),'Removed labels must not appear in the page');
$ok(str_contains($view,'lab-trip-restored')&&str_contains($view,'lab-docs-download'),'Summary and scan download controls missing');
$ok(!str_contains($view,'<span>Статус</span>')&&!str_contains($view,'data-request-issues'),'Status column and hover issue list must be removed');
$ok(substr_count($view,'<?=csrfField()?>')===4,'Autosave, upload and both review actions must include CSRF protection');
$ok(str_contains($view,'data-autosave-form')&&str_contains($view,'data-upload-form')&&str_contains($view,'trip-completion.js'),'Autosave UI hooks missing');
$ok(substr_count($view,'name="pickup_interval"')===1&&!str_contains($view,'type="datetime-local"'),'Pickup date and times must use one compact field');
$ok(str_contains($service,"ORDER BY wt.business_id DESC,wt.id DESC")&&str_contains($service,"ORDER BY CAST(fr.zayavka_id AS UNSIGNED) DESC"),'Trips and requests must be ordered by descending identifiers');
$ok(str_contains($service,"createFromFormat('!d.m.y H:i'")&&str_contains($service,"\$date.' '.\$parts[6]"),'Departure must reuse the arrival date');
$ok(!str_contains($view,'>Сохранить</button>')&&!str_contains($view,'>Загрузить ТН</button>'),'Manual save/upload buttons must not remain');
$ok(str_contains($javascript,"form.addEventListener('change'")&&str_contains($javascript,"picker.addEventListener('change'")&&str_contains($javascript,"Accept: 'application/json'"),'Automatic save/upload client contract missing');
$ok(str_contains($javascript,"event.inputType.startsWith('insert')")&&str_contains($javascript,'formatInterval')&&str_contains($javascript,'data-document-count'),'Numeric interval mask or live document counter missing');
$ok(str_contains($javascript,'data-preview-url')&&str_contains($javascript,'updateTripSummary')&&str_contains($javascript,'applySearch'),'Preview, trip summary, and live search missing');
$ok(str_contains($controller,'wantsJson()')&&str_contains($controller,"'missing_summary'")&&str_contains($controller,"'document_count'"),'AJAX response contract missing');
$ok(str_contains($styles,'grid-template-columns:minmax(180px,1fr)')&&str_contains($styles,'.logistics-trip-summary'),'Full-width one-row workspace contract missing');
$ok(!str_contains($styles,'box-shadow:inset 3px 0 0'),'Left accent stripe must not remain');
$ok(str_contains($view,'class="lab-docs-name"')&&str_contains($styles,'.lab-docs-name'),'Document names must remain visible');
$ok(str_contains($styles,'accent-color:var(--accent')&&str_contains($styles,'min-height:64px')&&str_contains($styles,'var(--success-bg')&&str_contains($styles,'var(--warning-bg'),'Compact rows must use ERP system states');
$ok(str_contains($controller,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')&&str_contains($service,'сводный_отчет.xlsx'),'Formatted XLSX report contract missing');
$ok(str_contains($service,'Рейс_{$tripNumber}_Заявка_{$requestNumber}_ТН_'),'Canonical TN filename missing trip/request identity');
$ok(substr_count($service,"wt.status IN ('in_progress','completed')")>=3&&str_contains($service,'doc.deleted_at IS NULL'),'Eligible trip status contract missing');
$ok(!str_contains($controller,'applyLocalMigrations'),'GET/action controller must not mutate schema');
echo "TRIP_COMPLETION_CONTRACT=PASS\n";
